  async initialize(
    _options?: InitializationOptions,
  ): Promise<InitializationContext> {
    this._isInitialized = true

    // Wait for Firebase auth + profile creation to finish before letting the app proceed.
    if (this.stateMachine) {
      await timeBootPhase('wait-for-profile', () => this.stateMachine!.waitForProfile())
    }

    // Populate system data on RundotGameAPI instance
    // Only set profile if auth callback hasn't already populated it (profileReady guarantees this).
    if (!this.rundotGameApi._profileData) {
      this.rundotGameApi._profileData = this.profile.getCurrentProfile()
    }
    this.rundotGameApi._deviceData = this.system.getDevice()
    this.rundotGameApi._environmentData = this.system.getEnvironment()

    this.rundotGameApi._localeData = this.rundotGameApi._mock?.locale || 'en-US'
    this.rundotGameApi._languageCodeData =
      this.rundotGameApi._mock?.languageCode || 'en'

    this.context = {
      initializeAsleep: false,
      safeArea: this.rundotGameApi._safeAreaData,
      launchParams: _options?.launchParams || {
        PLAYGROUND_LAUNCH_PARAMS_KEY: 'PLAYGROUND_LAUNCH_PARAMS_VALUE',
      },
      shareParams: _options?.shareParams || {
        PLAYGROUND_SHARE_PARAMS_KEY: 'PLAYGROUND_SHARE_PARAMS_VALUE',
      },
      shareLinkId: _options?.shareParams ? 'sandbox-share-id' : undefined,
    }

    // Upload server config before hiding the overlay so simulation APIs work immediately.
    const initPlaygroundConfig = getPlaygroundConfig()
    if (
      initPlaygroundConfig?.hasServerConfig &&
      initPlaygroundConfig.gameId &&
      initPlaygroundConfig.gameManagerUrl
    ) {
      try {
        const client = await getFirebaseClient()
        const user = client.getCurrentUser()
        if (user) {
          await timeBootPhase('server-config-upload', () =>
            this.uploadServerConfig(
              user,
              initPlaygroundConfig,
            ),
          )
        }
      } catch (err) {
        console.warn(
          '[RUN:playground] Initial config upload failed (proceeding anyway):',
          err,
        )
      }
    } else {
      markBootPhase('server-config-upload:skipped')
    }

    // Signal that the playground is fully ready for gameplay
    markBootPhase('game-ready')
    if (this.stateMachine) {
      this.stateMachine.markGameReady()
    }

    return this.context
  }

