  private async handleMenuButtonClicked() {
    if (this.state === PlaygroundHostState.PLAYING) {
      this.triggerLifecycleEvent(RundotGameMessageId.PAUSE)
      this.state = PlaygroundHostState.PAUSED
    }

    const actionSheetItems: MockActionSheetItem[] = []

    const awakeAction: MockActionSheetItem = {
      label: '⏰ Awake',
      id: 'awakeAction',
    }
    const sleepAction: MockActionSheetItem = {
      label: '💤 Sleep',
      id: 'sleepAction',
    }
    const quitAction: MockActionSheetItem = {
      label: '🛑 Quit',
      id: 'quitAction',
    }
    const playAction: MockActionSheetItem = {
      label: '▶️ Play',
      id: 'playAction',
    }

    if (this.state === PlaygroundHostState.PAUSED) {
      actionSheetItems.push(sleepAction)
    } else if (this.state === PlaygroundHostState.SLEEPING) {
      actionSheetItems.push(awakeAction)
    }

    if (this.state !== PlaygroundHostState.TERMINATED) {
      actionSheetItems.push(quitAction)
    } else if (this.state === PlaygroundHostState.TERMINATED) {
      actionSheetItems.push(playAction)
    }

    const action = await this.showActionSheetOverlay(actionSheetItems)

    if (action === awakeAction.id) {
      this.tryAwake()
    } else if (action === sleepAction.id) {
      this.trySleep()
    } else if (action === playAction.id) {
      this.tryPlay()
    } else if (action === quitAction.id) {
      this.tryQuit()
    } else {
      this.tryResume()
    }
  }

  private tryAwake() {
    if (this.state === PlaygroundHostState.SLEEPING) {
      this.triggerLifecycleEvent(RundotGameMessageId.AWAKE)
      this.state = PlaygroundHostState.PAUSED
    }
  }

  private trySleep() {
    if (this.state === PlaygroundHostState.PAUSED) {
      this.triggerLifecycleEvent(RundotGameMessageId.SLEEP)
      this.state = PlaygroundHostState.SLEEPING
    }
  }

  private tryPlay() {
    if (this.state === PlaygroundHostState.TERMINATED) {
      this.triggerLifecycleEvent(RundotGameMessageId.AWAKE)
      this.state = PlaygroundHostState.PAUSED
      this.triggerLifecycleEvent(RundotGameMessageId.RESUME)
      this.state = PlaygroundHostState.PLAYING
    }
  }

  private tryQuit() {
    if (this.state === PlaygroundHostState.PLAYING) {
      this.triggerLifecycleEvent(RundotGameMessageId.PAUSE)
      this.state = PlaygroundHostState.PAUSED
    }

    if (this.state === PlaygroundHostState.PAUSED) {
      this.triggerLifecycleEvent(RundotGameMessageId.SLEEP)
      this.state = PlaygroundHostState.SLEEPING
    }

    if (this.state === PlaygroundHostState.SLEEPING) {
      this.triggerLifecycleEvent(RundotGameMessageId.QUIT)
      this.state = PlaygroundHostState.TERMINATED
    }
  }

  private tryResume() {
    if (this.state === PlaygroundHostState.PAUSED) {
      this.triggerLifecycleEvent(RundotGameMessageId.RESUME)
      this.state = PlaygroundHostState.PLAYING
    }
  }

