// Host-facing HTTP implementation of ShopApi against the real shop routes
// (/v1/shop storefront reads + /v1/shop-orders purchase lifecycle). Firebase-free:
// auth + base URL come from the injected BackendHttpDeps, so any host
// (PlaygroundHost, Telegram/Steam shells) can construct it.
// Do NOT import from barrel exports (shop/index.ts).

import {
  ShopApi,
  StorefrontResponse,
  StorefrontItem,
  ShopPurchaseResponse,
  ShopOrderHistoryResponse,
} from './ShopApi'
import { RundotApiError } from '../errors'
import { authedBackendFetch } from '../http/backendHttpDeps'
import type { BackendHttpDeps } from '../http/backendHttpDeps'

export interface HttpShopApiOptions {
  /** Version tag whose server config the storefront resolves (`tagId`), e.g. `private` in the playground. */
  versionTag?: string
}

/**
 * Purchase-flow error codes with a dedicated response shape
 * (server/cloud-run/src/controllers/shopOrder.controller.ts): these put the
 * machine code in `error` with `message` alongside, while every other shop
 * error puts the human message in `error` and the code in `code`.
 */
type PurchaseFlowErrorCode = 'stale_catalog' | 'insufficient_funds'

const PURCHASE_FLOW_CODES: ReadonlySet<string> = new Set<PurchaseFlowErrorCode>(
  ['stale_catalog', 'insufficient_funds'],
)

interface ParsedShopError {
  code: string
  message: string
  currentConfigId?: string
  balance?: number
  deficit?: number
}

function parseShopErrorBody(status: number, text: string): ParsedShopError {
  let body: Record<string, unknown>
  try {
    const parsed: unknown = JSON.parse(text)
    if (parsed === null || typeof parsed !== 'object') {
      return { code: 'unknown', message: text || `Request failed (${status})` }
    }
    body = parsed as Record<string, unknown>
  } catch {
    return { code: 'unknown', message: text || `Request failed (${status})` }
  }
  const rawError = typeof body.error === 'string' ? body.error : undefined
  const message = typeof body.message === 'string' ? body.message : undefined

  if (rawError && PURCHASE_FLOW_CODES.has(rawError)) {
    return {
      code: rawError,
      message: message ?? rawError,
      currentConfigId:
        typeof body.currentConfigId === 'string'
          ? body.currentConfigId
          : undefined,
      balance: typeof body.balance === 'number' ? body.balance : undefined,
      deficit: typeof body.deficit === 'number' ? body.deficit : undefined,
    }
  }

  return {
    code: typeof body.code === 'string' ? body.code : 'unknown',
    message: message ?? rawError ?? (text || `Request failed (${status})`),
  }
}

export class HttpShopApi implements ShopApi {
  private readonly gameId: string
  private readonly deps: BackendHttpDeps
  private readonly versionTag?: string
  private cachedConfigId: string | null = null
  private fundingHintLogged = false

  constructor(
    gameId: string,
    deps: BackendHttpDeps,
    opts: HttpShopApiOptions = {},
  ) {
    this.gameId = gameId
    this.deps = deps
    this.versionTag = opts.versionTag
  }

  /** Drop the cached storefront configId; PlaygroundHost calls this on HMR config re-upload. */
  clearCatalogCache(): void {
    this.cachedConfigId = null
  }

  private tagQuery(): string {
    return this.versionTag
      ? `?tagId=${encodeURIComponent(this.versionTag)}`
      : ''
  }

  private async request<T>(
    method: 'GET' | 'POST',
    path: string,
    body?: Record<string, unknown>,
  ): Promise<T> {
    const response = await authedBackendFetch(this.deps, method, path, body)
    if (!response.ok) {
      throw this.toApiError(response.status, await response.text())
    }
    return response.json() as Promise<T>
  }

  private toApiError(status: number, text: string): RundotApiError {
    const parsed = parseShopErrorBody(status, text)

    if (parsed.code === 'stale_catalog') {
      if (parsed.currentConfigId) this.cachedConfigId = parsed.currentConfigId
      return new RundotApiError('stale_catalog', parsed.message, status)
    }

    if (parsed.code === 'insufficient_funds') {
      const detail = [
        parsed.balance !== undefined ? `balance: ${parsed.balance}` : null,
        parsed.deficit !== undefined ? `deficit: ${parsed.deficit}` : null,
      ]
        .filter(Boolean)
        .join(', ')
      if (!this.fundingHintLogged) {
        this.fundingHintLogged = true
        console.info(
          '[RUN:shop] Purchase failed: insufficient funds. Fund the test wallet via the in-playground store (RundotGameAPI.iap.openStore()).',
        )
      }
      return new RundotApiError(
        'insufficient_funds',
        detail ? `${parsed.message} (${detail})` : parsed.message,
        status,
      )
    }

    if (parsed.code === 'config-not-found') {
      return new RundotApiError(
        'config-not-found',
        'This game has no shop config. Add rundot/shop.config.json and reload — see the Shop API docs for the format.',
        status,
      )
    }

    return new RundotApiError(parsed.code, parsed.message, status)
  }

  private async fetchStorefront(): Promise<StorefrontResponse> {
    const storefront = await this.request<StorefrontResponse>(
      'GET',
      `/v1/shop/games/${this.gameId}/storefront${this.tagQuery()}`,
    )
    if (storefront.configId) this.cachedConfigId = storefront.configId
    return storefront
  }

  async getCatalog(
    includeInactive?: boolean,
    includeExpired?: boolean,
    includeUnreleased?: boolean,
  ): Promise<StorefrontResponse> {
    const storefront = await this.fetchStorefront()
    // Server ignores the include* flags — visibility is filtered client-side (matches H5ShopHandler).
    const now = Date.now()
    return {
      ...storefront,
      items: storefront.items.filter((item) => {
        if (!includeInactive && !item.active) return false
        if (!includeExpired && item.expiresAt !== null && item.expiresAt <= now)
          return false
        if (
          !includeUnreleased &&
          item.releasedAt !== null &&
          item.releasedAt > now
        )
          return false
        return true
      }),
    }
  }

  async getItemDetail(itemId: string): Promise<StorefrontItem> {
    const response = await this.request<{
      configId: string
      item: StorefrontItem
    }>(
      'GET',
      `/v1/shop/games/${this.gameId}/items/${encodeURIComponent(itemId)}${this.tagQuery()}`,
    )
    if (response.configId) this.cachedConfigId = response.configId
    return response.item
  }

  purchase(
    itemId: string,
    idempotencyKey: string,
  ): Promise<ShopPurchaseResponse> {
    return this.createOrder(itemId, idempotencyKey)
  }

  purchaseCollectionItem(
    collectionId: string,
    itemId: string,
    idempotencyKey: string,
  ): Promise<ShopPurchaseResponse> {
    return this.createOrder(itemId, idempotencyKey, collectionId)
  }

  private async createOrder(
    itemId: string,
    idempotencyKey: string,
    collectionId?: string,
  ): Promise<ShopPurchaseResponse> {
    if (!this.cachedConfigId) {
      await this.fetchStorefront()
    }
    if (!this.cachedConfigId) {
      throw new RundotApiError(
        'internal',
        'Storefront response did not include a configId; cannot pin a catalog version for purchase.',
        0,
      )
    }
    return this.request<ShopPurchaseResponse>('POST', '/v1/shop-orders', {
      gameId: this.gameId,
      itemId,
      configId: this.cachedConfigId,
      idempotencyKey,
      ...(this.versionTag ? { tagId: this.versionTag } : {}),
      ...(collectionId ? { collectionId } : {}),
    })
  }

  getOrder(orderId: string): Promise<ShopPurchaseResponse> {
    return this.request<ShopPurchaseResponse>(
      'GET',
      `/v1/shop-orders/${encodeURIComponent(orderId)}`,
    )
  }

  getOrderHistory(options?: {
    limit?: number
  }): Promise<ShopOrderHistoryResponse> {
    const qs = options?.limit ? `?limit=${options.limit}` : ''
    return this.request<ShopOrderHistoryResponse>(
      'GET',
      `/v1/shop-orders/games/${this.gameId}/history${qs}`,
    )
  }

  requestRefund(
    orderId: string,
    reasonCode: string,
  ): Promise<ShopPurchaseResponse> {
    return this.request<ShopPurchaseResponse>(
      'POST',
      `/v1/shop-orders/${encodeURIComponent(orderId)}/refund`,
      {
        reasonCode,
      },
    )
  }
}
